var SUS_LOG = "@ROOT@/modlog.txt";
/* ===== Susanoo runtime (char-susanoo, ActorId 193301) -- appended to data/js/gameplay/playertrigger/PlayerTriggerFuncs by bbmod =====
   0.1.5: his own copy of the part of EX Hakumen's runtime (mods/ex-hakumen/runtime.js 0.5.11) he ran on, so he needs no
   EX Hakumen (D7). EX Hakumen loses the Susanoo form (the lead, 2026-10-23); this file is Susanoo's from here on.
   He is always in the form (forever): no drain, no return, no transformation. What it does:
   - the form: his replace map MOD_sus_form is kept on him from his first tick and after each revive; a Hakumen state he
     can stand in before it is on (an entrance, idle) is started again as Susanoo's;
   - SP (slot 3) is his super gauge, kept under 100: attack hit +0.6, Skill hit +2 (0.1.14), kill +6 (+14 with Void Hunger 19331,
     +10 more with Eternal Void 19330, +6 more for a beam kill), Retribution block +15, passing through an attack in
     Vanishing Step +8 with 19348 + 19359; Eternal Void (19330) feeds 50% more; Void Hunger raises a stone where an
     enemy falls (his bullet 19330102);
   - MP slots: 7 at 100 (the form), 8 at 0, 4 / 5 / 6 up while he attacks / uses a Skill / steps and 0.25 s after;
   - the held beam: MP taken as each phase starts, one scene effect per phase (his hsx_beam2 / hsx_beam3, the fade at
     the end) started on his mouth and moved with him;
   - the camera push-ins (this PC's Susanoo only), the co-op marker MOD_sus_coop (no boss pull-out in co-op), the boss
     stagger guard, the gauge across rooms.
   Trigger rows 193900-193907 call it (bbee-actors BB_SELF_TRIGGERS[193301]); every entry point acts on BaseID 193301
   only. EX Hakumen's runtime is called by his own rows 191900-191907, which Susanoo no longer carries, so the two never
   act on the same hero. Log lines start with "SUS". DEV ONLY: with globalThis.EXH_DEV_GAUGE or SUS_DEV_GAUGE set the
   gauge never drops under 50. */
var SUSRT = (function () {
    /**
     * Susanoo's runtime: one module, one state per player
     * @returns {Object} the entry points the trigger functions call (start, tick, atk, sk, sup, kill, hurt, dodge)
     */
    var U = Util_1.U, ID = 193301, LOGP = (typeof SUS_LOG === "string" ? SUS_LOG : "");
    try {                                                // a test window (-bbwin N, N > 1) writes to its own modlog<N>.txt, as dev-testroom does
        var av = csharp_1.System.Environment.GetCommandLineArgs(), W = 1;
        for (var ai = 0; ai < av.Length - 1; ai++) if (String(av.get_Item(ai)).toLowerCase() == "-bbwin") W = Math.max(1, parseInt(av.get_Item(ai + 1)) || 1);
        if (W > 1 && LOGP) LOGP = LOGP.replace(/\.txt$/, W + ".txt");
    } catch (x) {
    }
    /* 0.1.14 (Pie Burritos, 2026-11-20: "he gains SP far too easily, so these moves can be spammed"): an attack hit
       feeds 0.6 (was 1.5) and a Skill hit 2 (was 4); kills, Retribution and the cards keep the amounts their texts give.
       Attack mashed on the dummy filled 7.6 SP a second in 0.1.13 (the beam's 40 every 5 s). The boss stagger window is
       2.0 s and the rest after it 3.0 s (were 1.2 and 5.0: bosses and elites stood unstaggerable 80% of the time; still
       never an endless stun, the rule of 2026-10-12). */
    var C = {
        feedHit: 0.6,
        feedSkill: 2,
        feedKill: 6,
        hunger: 14,
        feast: 10,
        retrib: 15,
        vstep: 8,
        formCap: 99,
        stagWin: 2.0,
        stagRest: 3.0
    };
    // his cards (EX Hakumen's Susanoo cards + 100; a card X is owned while he holds its trigger X*10+1)
    var EV = 19330, HUNGER = 19331, ORBS = 19347, VSTEP = 19348, STRIDE = 19359, BEAM = 19350;
    var FORM = "MOD_sus_form", COOP = "MOD_sus_coop", BLOCKED = "MOD_sus_blocked";

    function blank() {
        /**
         * one state per player: two Susanoos in a co-op fight keep their own
         * @returns {Object} a fresh per-player state
         */
        return {
            gen: -1, lastAct: "", seen: {}, n: 0, logged: 0, slotLog: 0, own: {}, ownT: -9, lastHit: {}, killSeen: {},
            roomKey: -2, roomPollT: -9, roomT: -9, formSP: -1, formUntil: -9, snapT: -9, old: null, cur: null
        };
    }

    var ST = {}, S = blank();

    function use(p) {
        /**
         * makes this player's state the current one (S), made on first use
         * @param {Object} p: the player
         */
        var k = "?";
        try {
            k = String(p.UniqueId)
        } catch (x) {
        }
        S = ST[k] || (ST[k] = blank())
    }

    var BORN = {born: 1, born2: 1, born3: 1, born_start: 1, s_born: 1, s_born2: 1, s_born3: 1, s_born_start: 1};

    function now() {
        /**
         * battle time in seconds (the wall clock when no battle runs)
         * @returns {number} seconds
         */
        try {
            var v = U.FpToFloat(csharp_1.GamePlay.BattleBase.Cur.BattleTimeFp);
            if (isFinite(v)) return v
        } catch (x) {
        }
        return Date.now() / 1000
    }

    function log(m) {
        /**
         * appends one "SUS" line to the mod log (at most 400 per room)
         * @param {string} m: the message
         */
        if (!LOGP || S.logged > 400) return;
        S.logged++;
        try {
            csharp_1.System.IO.File.AppendAllText(LOGP, (new Date()).toISOString() + " SUS " + m + "\n")
        } catch (x) {
        }
    }

    function fp(n) {
        /**
         * float to fixed-point
         * @param {number} n: the float
         * @returns {*} the fixed-point value
         */
        return U.FloatToFp(n)
    }

    function f(v) {
        /**
         * fixed-point to float (0 if it fails)
         * @param {*} v: the fixed-point value
         * @returns {number} the float
         */
        try {
            return U.FpToFloat(v)
        } catch (x) {
            return 0
        }
    }

    function has(p, idx) {
        /**
         * the buff is on the player
         * @param {Object} p: the player
         * @param {string|int} idx: the buff id
         * @returns {boolean} true if the buff is on
         */
        try {
            return !!p.BuffMgr.Find(idx)
        } catch (x) {
            return false
        }
    }

    function add(p, idx, dur) {
        /**
         * adds a buff (strength 1, one stack); a failure is logged
         * @param {Object} p: the player
         * @param {string|int} idx: the buff id
         * @param {number} dur: duration in seconds
         */
        try {
            p.BuffMgr.AddBuff(idx, fp(dur), fp(1), 1, p)
        } catch (x) {
            log("buff " + idx + " failed: " + x)
        }
    }

    function rm(p, idx) {
        /**
         * removes a buff
         * @param {Object} p: the player
         * @param {string|int} idx: the buff id
         */
        try {
            p.BuffMgr.Remove(idx)
        } catch (x) {
        }
    }

    function own(p, pid) {
        /**
         * the Potential is owned (it's trigger, pid*10+1), cached 2 s
         * @param {Object} p: player trigger
         * @param {int} pid: pid*10+1
         */
        var t = now();
        if (t - S.ownT > 2 || t < S.ownT) {
            S.own = {};
            S.ownT = t
        }
        var k = pid * 10 + 1;
        if (!(k in S.own)) {
            var v = false;
            try {
                v = !!p.TriggerMgr.FindTrigger(k)
            } catch (x) {
            }
            S.own[k] = v
        }
        return S.own[k];
    }

    function sp(p) {
        /**
         * his SP, the super gauge (MP slot 3); 0 if it cannot be read
         * @param {Object} p: the player
         * @returns {number} the SP
         */
        try {
            return f(p.Attr.GetMP(3))
        } catch (x) {
            return 0
        }
    }

    function setSP(p, v) {
        /**
         * sets his SP (MP slot 3) to v
         * @param {Object} p: the player
         * @param {number} v: the new SP
         */
        try {
            p.Attr.ChangeMPBy(fp(v - sp(p)), 3)
        } catch (x) {
        }
    }

    function stage() {
        /**
         * the run's room (phase * 1000 + room), or -1 if unknown
         * @returns {int} phase * 1000 + room, or -1
         */
        var mods = ["GamePlay/BattleBreedRun/BattleBreedRun", "GamePlay/BattleBreedRun/BattleBreedRunBase"];
        for (var i = 0; i < mods.length; i++) {
            try {
                var M = require(mods[i]).default, B = M && (M.Instance || M.SilentInstance || M.s_instanceBase);
                if (B && B.currentPhase != null) return Number(B.currentPhase) * 1000 + Number(B.currentStageIndex || 0)
            } catch (x) {
            }
        }
        return -1;
    }

    // the gauge across rooms: a new room is seen from the run's room key (polled every 0.2 s) or from an entrance; the
    // stock OnBorn refill at a spawn is taken back to what he had (two snapshots 0.3 s apart give the value from before)
    function snap(t) {
        /**
         * snapshot of the carried SP, at most one every 0.3 s; the one before is kept in S.old
         * @param {number} t: battle time in seconds
         */
        if (t >= S.snapT && t - S.snapT < 0.3) return;
        S.snapT = t;
        S.old = S.cur;
        S.cur = {form: S.formSP}
    }

    function pre(v) {
        /**
         * the SP from before a stock OnBorn refill: the older snapshot if v is more than 20 over it
         * @param {number} v: the SP now
         * @returns {number} the SP to carry
         */
        var o = S.old ? S.old.form : -1;
        return (o >= 0 && v > o + 20) ? o : v
    }

    function arrive(p, t, why) {
        /**
         * a new room (at most one every 2 s): resets the log caps and carries the gauge for 1.5 s
         * @param {Object} p: the player
         * @param {number} t: battle time in seconds
         * @param {string} why: what showed the new room, written to the log
         * @returns {boolean} true if it counted as a new room
         */
        if (t >= S.roomT && t - S.roomT < 2) return false;
        S.roomT = t;
        S.logged = 0;
        S.slotLog = 0;                       // the log cap is per room
        S.formSP = pre(S.formSP);
        S.formUntil = t + 1.5;
        log("new room (" + why + "): SP " + sp(p).toFixed(1) + ", carried " + S.formSP.toFixed(1));
        return true;
    }

    function room(p, t) {
        /**
         * polls the run's room key every 0.2 s; a changed key (not the first one seen) is a new room
         * @param {Object} p: the player
         * @param {number} t: battle time in seconds
         * @returns {boolean} true if a new room was entered
         */
        if (t >= S.roomPollT && t - S.roomPollT < 0.2) return false;
        S.roomPollT = t;
        var k = stage();
        if (k < 0 || k === S.roomKey) return false;
        var first = S.roomKey === -2;
        S.roomKey = k;
        if (first) return false;
        return arrive(p, t, "stage " + k);
    }

    function fresh() {
        /**
         * a new battle (the actor id counter went back): clears the per-battle state, the stagger guards and the zoom
         */
        var g = -1;
        try {
            g = csharp_1.GamePlay.BattleBase.Cur.m_ActorUniqueIdGen
        } catch (x) {
        }
        if (g < S.gen) {
            S.seen = {};
            S.n = 0;
            S.lastAct = null;
            S.lastHit = {};
            S.killSeen = {};
            S.own = {};
            S.ownT = -9;
            SG = {};
            zoomOff()
        }
        S.gen = g
    }

    function mine(p) {
        /**
         * the actor is Susanoo (BaseID 193301)
         * @param {Object} p: the actor
         * @returns {boolean} true if it is Susanoo
         */
        try {
            return p.BaseID === ID
        } catch (x) {
            return false
        }
    }

    // Hakumen's own states he can be standing in before his replace map is on (a room's entrance, idle): started again
    // as Susanoo's, so his first frames are not Hakumen's
    var HAKU_START = {born: 1, born2: 1, born3: 1, born_start: 1, born_start_2: 1, stand: 1, standby: 1, run: 1};

    function keep(p, a) {
        /**
         * keeps the form's replace map (MOD_sus_form) on him while alive; a Hakumen start state is started again as Susanoo's
         * @param {Object} p: the player
         * @param {string} a: the current action name
         */
        try {
            if (p.IsDead) return
        } catch (x) {
        }
        if (has(p, FORM)) return;
        add(p, FORM, 36000);
        log("form kept (" + a + ")");
        if (HAKU_START[a]) {
            try {
                p.ActionMgr.ChangeAction("s_" + a)
            } catch (x) {
            }
        }
    }

    function feed(p, v, why) {
        /**
         * his gauge (never to 100)
         * @param {Object} p: the player
         * @param {number} v: SP to add (x1.5 with Eternal Void)
         * @param {string} why: reason written to the log
         */
        if (!(v > 0)) return;
        if (own(p, EV)) v *= 1.5;
        var s = sp(p), to = Math.min(C.formCap, s + v);
        if (to <= s) return;
        try {
            p.Attr.ChangeMPBy(fp(to - s), 3)
        } catch (x) {
            return
        }
        log("feed +" + (to - s).toFixed(1) + " " + why + " -> " + to.toFixed(1));
    }

    function slots(p) {
        /**
         * MP 7 = 100 (the form), MP 8 = 0; MP 4 / 5 / 6: attack / Skill / step
         * @param {Object} p: the player
         */
        var want = [[7, 100], [8, 0]];
        // the follow-ups that cross buttons (step > Attack slide, step > Skill thrust, Attack > Summon dagger, Skill > Summon
        // strike) are starting rows that need their slot: a PreSkillOrder naming a row of another button's group never
        // matched in game (EX Hakumen 0.4.0)
        try {
            var an = String(p.ActionMgr.CurrentActionName || ""), tn = now(),
                K = S.kindT || (S.kindT = {4: -9, 5: -9, 6: -9});
            if (/^s_(jab|claw|palm|sweep2?|crescent|claws\w*|kick\w*|cal\d|slide2?|dive\w*|air\d?|charge\w*)$/.test(an)) K[4] = tn;
            if (/^s_(earth|flame|thrust2?|iaido\w*|eruption\w*)$/.test(an)) K[5] = tn;
            if (/^s_(step\d?|stepend)$/.test(an)) K[6] = tn;
            for (var k = 4; k <= 6; k++) {
                if (K[k] > tn) K[k] = -9;   // a new battle restarts the clock
                want.push([k, tn - K[k] <= 0.25 ? 100 : 0]);
            }
        } catch (x) {
        }
        for (var i = 0; i < want.length; i++) {
            try {
                var cur = f(p.Attr.GetMP(want[i][0]));
                if (Math.abs(cur - want[i][1]) > 0.5) {
                    p.Attr.ChangeMPBy(fp(want[i][1] - cur), want[i][0]);
                    if (S.slotLog < 16) {
                        S.slotLog++;
                        log("slot " + want[i][0] + ": " + cur.toFixed(0) + " -> " + f(p.Attr.GetMP(want[i][0])).toFixed(0))
                    }
                }
            } catch (x) {
                if (S.slotLog < 16) {
                    S.slotLog++;
                    log("slot " + want[i][0] + " failed: " + x)
                }
            }
        }
    }

    function once(sid) {
        /**
         * true the first time a skill session is seen (the memory is cleared past 400)
         * @param {string} sid: the session key ("a" or "s" + SkillSessionId)
         * @returns {boolean} true if not seen before
         */
        if (S.seen[sid]) return false;
        if (++S.n > 400) {
            S.seen = {};
            S.n = 1
        }
        S.seen[sid] = 1;
        return true
    }

    function actOf(a) {
        /**
         * the attacker's current action name ("" if unknown)
         * @param {Object} a: the hit info
         * @returns {string} the action name
         */
        try {
            var at = a.Attacker;
            if (at && at.ActionMgr) return String(at.ActionMgr.CurrentActionName || "")
        } catch (x) {
        }
        return ""
    }

    function isFoe(a) {
        /**
         * the actor is an enemy, not a prop (Stuff) or a trap (Trap)
         * @param {Object} a: the actor
         * @returns {boolean} true if it is an enemy
         */
        try {
            var g = a && a.TagMgr;
            if (!g) return false;
            return !(g.HasTag("Stuff") || g.HasTag("Trap"))
        } catch (x) {
            return false
        }
    }

    /* "also make sure susannno cant infinitely stun bosses or stagger them with his skills" (design note, 2026-10-12): his
       first hit on a boss opens a window of C.stagWin s in which his hits stagger as they always did; then the boss takes the
       game's armour buff (2301) for C.stagRest s. Damage untouched; bosses only (MonsterConfig ExtParams Tag=Boss). */
    var SG = {}, MROW = {};

    function bossy(a) {
        /**
         * the actor is a boss (MonsterConfig ExtParams Tag=Boss), cached per BaseID
         * @param {Object} a: the actor
         * @returns {boolean} true if it is a boss
         */
        var id = a.BaseID;
        if (MROW[id] !== undefined) return MROW[id];
        var b = false;
        try {
            var r = require("Gen/Xlsx").Xlsx.MonsterConfig.Get(id),
                e = r ? (r.ExtParams !== undefined ? r.ExtParams : r.extParams) : "";
            b = /Boss/.test((String(e || "").match(/Tag=([^;]*)/) || [])[1] || "")
        } catch (x) {
        }
        return (MROW[id] = b);
    }

    function stagHit(p, v) {
        /**
         * his hit on a boss opens a stagger window, unless a window or its rest is still running
         * @param {Object} p: the player
         * @param {Object} v: the actor hit
         */
        if (!v) return;
        try {
            if (!bossy(v)) return;
            var id = v.UniqueId, t = now(), g = SG[id];
            if (g && t < g.w + C.stagWin + C.stagRest) return;
            SG[id] = {a: v, w: t, on: false};
            log("stagger window opens on boss " + v.BaseID);
        } catch (x) {
        }
    }

    function stagTick(p, t) {
        /**
         * a boss whose stagger window closed takes the armour buff 2301 for C.stagRest s; old entries are dropped
         * @param {Object} p: the player
         * @param {number} t: battle time in seconds
         */
        for (var id in SG) {
            var g = SG[id];
            if (g.on || t < g.w + C.stagWin) {
                if (g.on && t > g.w + C.stagWin + C.stagRest + 30) delete SG[id];
                continue
            }
            g.on = true;
            try {
                if (!g.a.IsDead) {
                    g.a.BuffMgr.AddBuff("2301", fp(C.stagRest), fp(10), 1, p);
                    log("boss " + g.a.BaseID + " resists stagger for " + C.stagRest + " s")
                }
            } catch (x) {
                log("stagger guard failed: " + x)
            }
        }
    }

    var BEAM_MP = {s_beam2: 25, s_beam3: 30, s_beam3b: 30};   // the held beam: MP taken as each phase starts
    /* The held beam's phases draw through the scene-effect player: one effect per phase (fx/, built in the kit from the
       boss's own beam), started when the phase starts, moved with him each tick, stopped when he leaves the beam; a phase
       that repeats (s_beam3 / s_beam3b) keeps its effect. sx, sy: phase 2 and 3 are 2.3 and 3.3 times phase 1's height.
       The effect's point is 1.13 ahead and 0.5 up in its own space; it is put on his mouth, measured against his feet
       facing forward in each phase's held pose (his held-pose export, VFX director 2026-11-05; phase 1 is placed by the
       tree's own entry): phase 2 1.08 ahead / 0.50 up; since 2026-11-06 every phase holds the same crouch, mouth 1.06 / 0.57 (animation director). */
    var BEAM_FX = {s_beam2: [2, 1.25, 2.3], s_beam3: [3, 1.4, 3.3], s_beam3b: [3, 1.4, 3.3]},   // phase, sx, sy
        MOUTH = {2: [1.06, 0.57], 3: [1.06, 0.57]},
        FXDIR = "Benediction/Susanoo/hsx_beam",
        BF = {hub: null, k: 0, dir: 1, sx: 1, sy: 1, z: null};

    function beamAt(p, k, dir, sx, sy) {
        /**
         * where a beam phase's effect goes so its point sits on his mouth
         * @param {Object} p: the player
         * @param {int} k: the beam phase (2 or 3)
         * @param {int} dir: facing, 1 or -1
         * @param {number} sx: the effect's horizontal scale
         * @param {number} sy: the effect's vertical scale
         * @returns {number[]} [x, y] in world space
         */
        var m = MOUTH[k] || MOUTH[2];
        return [p.Position.x + dir * (m[0] - 1.13 * sx), p.Position.y + m[1] - 0.5 * sy]
    }

    function scene() {
        /**
         * the battle's scene (null outside a battle)
         * @returns {Object|null} the scene
         */
        try {
            return csharp_1.GamePlay.BattleBase.Cur.BattleScene
        } catch (x) {
            return null
        }
    }

    function beamStop(fade, p) {
        /**
         * stops the running beam effect; with fade, the fade effect plays where it was
         * @param {boolean} fade: play the fade effect
         * @param {Object} p: the player
         */
        if (!BF.hub) return;
        var sc = scene(), V2 = csharp_1.UnityEngine.Vector2;
        try {
            if (sc) sc.StopSceneEffect(BF.hub, false)
        } catch (x) {
            log("beam fx stop EXC " + x)
        }
        var k = BF.k;
        BF.hub = null;
        BF.k = 0;
        if (fade && sc && p) {
            try {
                var o = beamAt(p, k, BF.dir, BF.sx, BF.sy);
                sc.StartSceneEffect(FXDIR + "_fade", new V2(o[0], o[1]), new V2(BF.dir * BF.sx, BF.sy), 0, 0)
            } catch (x) {
            }
        }
    }

    function beamFollow(p) {
        /**
         * moves the running beam effect onto his mouth (its depth is kept)
         * @param {Object} p: the player
         */
        if (!BF.hub) return;
        try {
            var tr = BF.hub.transform, q = tr.position, o = beamAt(p, BF.k, BF.dir, BF.sx, BF.sy);
            if (BF.z === null) BF.z = q.z;
            tr.position = new csharp_1.UnityEngine.Vector3(o[0], o[1], BF.z)
        } catch (x) {
        }
    }

    function teamFx(p) {
        /**
         * how this game draws p's script-made effects: "full" for this game's own player, else the game's
         * "Teammate Effect Intensity" (Settings, Graphics): "off", "low" or "full" (Standard)
         * @param {Object} p: the player
         * @returns {string} "full", "low" or "off"
         */
        try {
            var B = csharp_1.GamePlay.BattleBase.Cur;
            if (!B || B.PlayerSelf === p) return "full";
            var s = csharp_1.ACERender.ACERenderPipeline.Current.Settings;
            if (s.PveTeammateEffectHide == 1) return "off";
            return s.PveTeammateEffectLevel == csharp_1.NOAH.VFX.VFXHubLOD.Max ? "full" : "low"
        } catch (x) {
            return "full"
        }
    }

    function beamFx(p, a) {
        /**
         * starts the effect of the beam phase action a starts; a repeated phase keeps its effect; outside the beam the
         * effect stops (fading on s_beam_end)
         * @param {Object} p: the player
         * @param {string} a: the new action name
         */
